// ===== eingebettet aus src/fehlerklassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const fehlerklassen = (() => {
const module = { exports: {} };
// Fehlerklassen und Statuscode-Mapping (Masterprompt 3, Bauplan 3).
// EPA-Fehler werden als Text "[EPA:<status>:<CODE>:<Vorgangs-ID|->] <Meldung>" geworfen,
// damit der Error-Handler (EPA-05) sie aus execution.error.message zurücklesen kann.

const FEHLERCODES = Object.freeze({
	UNGUELTIGES_FORMAT: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNGUELTIGER_AUSLOESER: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNBEKANNTER_STATUS: { status: 400, klasse: 'Eingabe', retrybar: false },
	AUTH_FEHLER: { status: 401, klasse: 'Authentifizierung', retrybar: false },
	KEINE_BERECHTIGUNG: { status: 403, klasse: 'Authentifizierung', retrybar: false },
	VORGANG_NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	KONFIG_NICHT_GEFUNDEN: { status: 404, klasse: 'Konfiguration', retrybar: false },
	NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	DUPLIKAT: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_STATUSWECHSEL: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_AUSLOESER: { status: 409, klasse: 'Konflikt', retrybar: false },
	VERSIONSKONFLIKT: { status: 409, klasse: 'Konflikt', retrybar: true },
	GESPERRT: { status: 409, klasse: 'Konflikt', retrybar: true },
	KONFIG_MEHRDEUTIG: { status: 409, klasse: 'Konfiguration', retrybar: false },
	FREIGABE_ABGELAUFEN: { status: 410, klasse: 'Freigabe', retrybar: false },
	EXTRAKTION_UNGUELTIG: { status: 422, klasse: 'LLM', retrybar: false },
	KONFIGURATIONSFEHLER: { status: 424, klasse: 'Konfiguration', retrybar: false },
	RATE_LIMIT: { status: 429, klasse: 'Upstream', retrybar: true },
	UPSTREAM_FEHLER: { status: 502, klasse: 'Upstream', retrybar: true },
	NICHT_ERREICHBAR: { status: 503, klasse: 'Upstream', retrybar: true },
	ZEITUEBERSCHREITUNG: { status: 504, klasse: 'Upstream', retrybar: true },
	UNBEKANNT: { status: 500, klasse: 'Unbekannt', retrybar: false },
});

// Bei diesen Codes bearbeitet eine andere Ausführung den Vorgang bzw. die Mail ist schon verarbeitet:
// der Vorgang wird NICHT auf "Eskaliert / Manuell" gesetzt (sonst würde ein Parallellauf gestört).
const OHNE_ESKALATION = Object.freeze(['VERSIONSKONFLIKT', 'GESPERRT', 'DUPLIKAT']);

const EPA_MUSTER = /^\[EPA:(\d{3}):([A-Z_]+):([^\]]*)\]\s*([\s\S]*)$/;

function formatEpaFehler(code, vorgangsId, meldung) {
	const def = FEHLERCODES[code] || FEHLERCODES.UNBEKANNT;
	return `[EPA:${def.status}:${FEHLERCODES[code] ? code : 'UNBEKANNT'}:${vorgangsId || '-'}] ${meldung || ''}`.trim();
}

/** Wirft einen EPA-Fehler (für Code-Nodes). */
function epaFehler(code, vorgangsId, meldung) {
	const err = new Error(formatEpaFehler(code, vorgangsId, meldung));
	err.epaCode = code;
	return err;
}

function parseEpaFehler(text) {
	if (typeof text !== 'string') return null;
	// n8n stellt der Meldung manchmal Präfixe voran; das Muster darf irgendwo in der ersten Zeile beginnen.
	const start = text.indexOf('[EPA:');
	if (start < 0) return null;
	const m = text.slice(start).match(EPA_MUSTER);
	if (!m) return null;
	return {
		status: Number(m[1]),
		code: m[2],
		vorgangsId: m[3] === '-' ? null : m[3],
		meldung: m[4].trim(),
	};
}

/** Entfernt personenbezogene Daten und kürzt (keine Mail-Inhalte im Fehlerlog). */
function bereinigeMeldung(text, maxLaenge = 300) {
	if (text === undefined || text === null) return '';
	let s = String(text)
		.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '<email>')
		.replace(/\+?\d[\d\s/().-]{7,}\d/g, '<nummer>')
		.replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/g, 'Bearer <token>')
		.replace(/\s+/g, ' ')
		.trim();
	if (s.length > maxLaenge) s = s.slice(0, maxLaenge - 1) + '…';
	return s;
}

function codeAusHttpStatus(status) {
	const n = Number(status);
	if (!Number.isFinite(n)) return null;
	if (n === 400 || n === 422) return 'UNGUELTIGES_FORMAT';
	if (n === 401) return 'AUTH_FEHLER';
	if (n === 403) return 'KEINE_BERECHTIGUNG';
	if (n === 404) return 'NICHT_GEFUNDEN';
	if (n === 408 || n === 504) return 'ZEITUEBERSCHREITUNG';
	if (n === 409) return 'DUPLIKAT';
	if (n === 429) return 'RATE_LIMIT';
	if (n === 503) return 'NICHT_ERREICHBAR';
	if (n >= 500 && n < 600) return 'UPSTREAM_FEHLER';
	return null;
}

function codeAusText(text) {
	const t = String(text || '');
	if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|timeout of \d+ms/i.test(t)) return 'ZEITUEBERSCHREITUNG';
	if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|service unavailable/i.test(t)) return 'NICHT_ERREICHBAR';
	if (/rate.?limit|too many requests/i.test(t)) return 'RATE_LIMIT';
	if (/invalid_grant|unauthori[sz]ed|token (has )?expired|invalid.?token|authentication failed|password authentication/i.test(t)) return 'AUTH_FEHLER';
	if (/forbidden|insufficient privileges|access denied|permission denied/i.test(t)) return 'KEINE_BERECHTIGUNG';
	if (/duplicate key|unique constraint/i.test(t)) return 'DUPLIKAT';
	return null;
}

/**
 * Klassifiziert einen Fehler.
 * @param {{message?: string, description?: string, httpCode?: string|number}} fehler
 */
function klassifiziereFehler(fehler) {
	const f = fehler || {};
	const epa = parseEpaFehler(f.message) || parseEpaFehler(f.description);
	let code;
	let vorgangsId = null;
	let meldung;
	if (epa) {
		code = FEHLERCODES[epa.code] ? epa.code : 'UNBEKANNT';
		vorgangsId = epa.vorgangsId;
		meldung = epa.meldung;
	} else {
		code = codeAusHttpStatus(f.httpCode) || codeAusText(`${f.message || ''} ${f.description || ''}`) || 'UNBEKANNT';
		meldung = f.message || f.description || '';
	}
	const def = FEHLERCODES[code];
	return {
		statuscode: def.status,
		fehlercode: code,
		klasse: def.klasse,
		retrybar: def.retrybar,
		eskalieren: !OHNE_ESKALATION.includes(code),
		vorgangsId,
		meldung: bereinigeMeldung(meldung),
	};
}

/**
 * Baut aus der Ausgabe des Error Trigger einen Fehlerlog-Eintrag (ohne Mail-Inhalte).
 * Error Trigger liefert entweder {execution, workflow} oder bei Trigger-Fehlern {trigger, workflow}.
 */
function ausErrorTrigger(json) {
	const j = json || {};
	const exec = j.execution || {};
	const err = exec.error || (j.trigger && j.trigger.error) || {};
	const k = klassifiziereFehler({
		message: err.message,
		description: err.description,
		httpCode: err.httpCode,
	});
	const node = (err.node && err.node.name) || exec.lastNodeExecuted || null;
	const workflow = j.workflow || {};
	return {
		statuscode: k.statuscode,
		fehlercode: k.fehlercode,
		klasse: k.klasse,
		retrybar: k.retrybar,
		eskalieren: k.eskalieren && Boolean(k.vorgangsId),
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
		execution_id: exec.id !== undefined && exec.id !== null ? String(exec.id) : null,
		execution_url: exec.url || null,
		modus: exec.mode || (j.trigger && j.trigger.mode) || null,
		vorgangs_id: k.vorgangsId,
		meldung: k.meldung,
	};
}

function escapeHtml(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function alarmHtml(eintrag) {
	const e = eintrag;
	const zeilen = [
		`<b>EPA-Fehler ${e.statuscode} ${escapeHtml(e.fehlercode)}</b> (${escapeHtml(e.klasse)})`,
		`Workflow: ${escapeHtml(e.workflow_name || e.workflow_id || '?')}`,
		`Node: ${escapeHtml(e.node || '?')}`,
		`Vorgang: ${escapeHtml(e.vorgangs_id || '–')}`,
		`Meldung: ${escapeHtml(e.meldung || '–')}`,
		e.retrybar ? 'Hinweis: vorübergehender Fehler, erneuter Versuch kann helfen.' : 'Hinweis: dauerhafter Fehler, bitte prüfen.',
	];
	if (e.execution_url) zeilen.push(`<a href="${escapeHtml(e.execution_url)}">Ausführung ${escapeHtml(e.execution_id)} öffnen</a>`);
	return zeilen.join('<br>');
}

module.exports = {
	FEHLERCODES,
	OHNE_ESKALATION,
	formatEpaFehler,
	epaFehler,
	parseEpaFehler,
	bereinigeMeldung,
	klassifiziereFehler,
	ausErrorTrigger,
	alarmHtml,
	escapeHtml,
};
return module.exports;
})();
// ===== Ende src/fehlerklassen.js =====

// ----- Node-Logik -----
const e = $input.first().json || {};
let jetzt = new Date().toISOString();
if (typeof e.jetzt === 'string' && e.jetzt.trim()) {
	if (!Number.isFinite(new Date(e.jetzt).getTime())) throw fehlerklassen.epaFehler('UNGUELTIGES_FORMAT', null, 'Eingabe "jetzt" ist kein gültiger Zeitpunkt');
	jetzt = new Date(e.jetzt).toISOString();
}
return [{ json: { jetzt, probelauf: e.probelauf === true } }];

// ===== eingebettet aus src/loeschen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const loeschen = (() => {
const module = { exports: {} };
// Lösch- und Aufräumjob (Masterprompt 7, Bauplan Datenschutz): Daten nur so lange wie nötig.
// - Vorgänge in einem Endstatus ("Abgeschlossen", "Ignoriert") nach aufbewahrung_tage seit der letzten Änderung,
//   samt Audit, Freigaben und Freigabe-Links. Offene oder eskalierte Vorgänge werden nie automatisch gelöscht.
// - Dedupe-Einträge (epa_verarbeitete_mails) nach aufbewahrung_tage.
// - Fehlerlog nach 90 Tagen (enthält nur IDs und technische Meldungen).
// - Ersetzte Rückfrage-Entwürfe im Postfach (nie gesendet, nie mehr gültig). Gelöscht wird nur, was nachweislich
//   ein Entwurf ist und die passende Freigabe-Kennung trägt. Outlook verschiebt ihn in "Gelöschte Elemente".

const ENDSTATUS = Object.freeze(['Abgeschlossen', 'Ignoriert']);
const FEHLERLOG_TAGE = 90;
const MAX_VORGAENGE = 200;
const MAX_ENTWUERFE = 50;
const TAG = 86400000;

function ms(t) {
	if (t === null || t === undefined || t === '') return NaN;
	const x = new Date(t).getTime();
	return Number.isFinite(x) ? x : NaN;
}

/**
 * @param {object} p
 * @param {string} p.jetzt
 * @param {object[]} p.vorgaenge  Zeilen aus epa_vorgaenge (mit updatedAt)
 * @param {object[]} p.freigaben  Zeilen aus epa_freigaben
 * @param {object} p.configs      kunde_id -> { aufbewahrung_tage, postfach, postfach_workflow_id } (auch inaktive Kunden)
 */
function planen({ jetzt, vorgaenge, freigaben, configs, maxVorgaenge = MAX_VORGAENGE, maxEntwuerfe = MAX_ENTWUERFE }) {
	const t = ms(jetzt);
	if (!Number.isFinite(t)) throw new Error(`Ungültiger Zeitpunkt "${jetzt}"`);
	const ohneConfig = new Set();
	const tage = (kunde) => {
		const c = configs[kunde];
		const n = c ? Number(c.aufbewahrung_tage) : NaN;
		if (!(n > 0)) {
			ohneConfig.add(kunde);
			return null;
		}
		return n;
	};

	// Ersetzte Entwürfe, die noch im Postfach liegen
	const offeneEntwuerfe = (freigaben || []).filter((f) => f && f.status === 'ersetzt' && f.entwurf_id && !f.entwurf_entfernt_am);
	const entwuerfe = [];
	for (const f of offeneEntwuerfe) {
		const c = configs[f.kunde_id];
		if (!c || !c.postfach_workflow_id || !c.postfach) continue;
		if (entwuerfe.length >= maxEntwuerfe) break;
		entwuerfe.push({ kunde_id: f.kunde_id, vorgangs_id: f.vorgangs_id, freigabe_id: f.freigabe_id, entwurf_id: f.entwurf_id, postfach: c.postfach, postfach_workflow_id: c.postfach_workflow_id });
	}
	const entwurfOffen = new Set(offeneEntwuerfe.map((f) => `${f.kunde_id}|${f.vorgangs_id}`));

	// Vorgänge nach Ablauf der Aufbewahrung
	const zuLoeschen = [];
	let zurueckgestellt = 0;
	for (const v of vorgaenge || []) {
		if (!v || !ENDSTATUS.includes(v.status)) continue;
		const n = tage(v.kunde_id);
		if (n === null) continue;
		const stand = ms(v.updatedAt);
		if (!Number.isFinite(stand) || stand + n * TAG > t) continue;
		// Erst den alten Entwurf aus dem Postfach entfernen, dann die Freigabe (sonst ginge die Zuordnung verloren).
		if (entwurfOffen.has(`${v.kunde_id}|${v.vorgangs_id}`)) {
			zurueckgestellt += 1;
			continue;
		}
		zuLoeschen.push({ kunde_id: v.kunde_id, vorgangs_id: v.vorgangs_id });
	}
	const vorgaengeListe = zuLoeschen.slice(0, maxVorgaenge);
	const schluessel = new Set(vorgaengeListe.map((v) => `${v.kunde_id}|${v.vorgangs_id}`));
	const freigabeIds = (freigaben || []).filter((f) => f && schluessel.has(`${f.kunde_id}|${f.vorgangs_id}`)).map((f) => ({ kunde_id: f.kunde_id, vorgangs_id: f.vorgangs_id, freigabe_id: f.freigabe_id }));

	const mailGrenzen = Object.keys(configs).map((k) => ({ kunde_id: k, n: tage(k) })).filter((x) => x.n !== null)
		.map((x) => ({ kunde_id: x.kunde_id, grenze: new Date(t - x.n * TAG).toISOString() }));

	return {
		vorgaenge: vorgaengeListe,
		freigaben: freigabeIds,
		entwuerfe,
		mail_grenzen: mailGrenzen,
		fehler_grenze: new Date(t - FEHLERLOG_TAGE * TAG).toISOString(),
		zurueckgestellt,
		verschoben: Math.max(0, zuLoeschen.length - maxVorgaenge) + Math.max(0, offeneEntwuerfe.length - entwuerfe.length),
		ohne_config: [...ohneConfig].sort(),
	};
}

/**
 * Darf der Entwurf gelöscht werden? Antwort von GET /messages/{id} mit fullResponse.
 * @returns {{ loeschen: boolean, erledigt: boolean, grund: string }}
 */
function entwurfPruefen(antwort, freigabeId, eigenschaftId) {
	const status = Number(antwort && antwort.statusCode);
	if (status === 404) return { loeschen: false, erledigt: true, grund: 'nicht_mehr_vorhanden' };
	if (status !== 200) return { loeschen: false, erledigt: false, grund: `http_${status || 'unbekannt'}` };
	const b = (antwort && antwort.body) || {};
	if (b.isDraft !== true) return { loeschen: false, erledigt: true, grund: 'kein_entwurf' };
	const prop = (b.singleValueExtendedProperties || []).find((p) => String(p.id).toLowerCase() === String(eigenschaftId).toLowerCase());
	if (!prop || prop.value !== freigabeId) return { loeschen: false, erledigt: true, grund: 'kennung_passt_nicht' };
	return { loeschen: true, erledigt: true, grund: 'entwurf_geloescht' };
}

function zusammenfassung(plan) {
	return {
		vorgaenge: plan.vorgaenge.length,
		freigaben: plan.freigaben.length,
		entwuerfe: plan.entwuerfe.length,
		zurueckgestellt: plan.zurueckgestellt,
		verschoben: plan.verschoben,
		ohne_config: plan.ohne_config,
		fehler_grenze: plan.fehler_grenze,
	};
}

module.exports = { ENDSTATUS, FEHLERLOG_TAGE, MAX_VORGAENGE, MAX_ENTWUERFE, planen, entwurfPruefen, zusammenfassung };
return module.exports;
})();
// ===== Ende src/loeschen.js =====

// ----- Node-Logik -----
// Auch inaktive Kunden: die Aufbewahrungsfrist gilt weiter. Ohne gültige Frist wird für den Kunden nichts gelöscht.
const l = $('Lauf vorbereiten').first().json;
const zeilen = (n) => $(n).all().map((i) => i.json).filter((z) => z && z.id !== undefined);
const configs = {};
for (const c of zeilen('Configs lesen')) {
	const pwf = /^[A-Za-z0-9]{8,32}$/.test(String(c.postfach_workflow_id || '')) ? c.postfach_workflow_id : null;
	const postfach = /^[^@<>\s]+@[^@<>\s]+$/.test(String(c.postfach || '')) ? String(c.postfach).toLowerCase() : null;
	configs[c.kunde_id] = { aufbewahrung_tage: Number(c.aufbewahrung_tage), postfach, postfach_workflow_id: pwf };
}
const p = loeschen.planen({ jetzt: l.jetzt, vorgaenge: zeilen('Abgeschlossene Vorgänge lesen'), freigaben: zeilen('Freigaben lesen'), configs });
const grenzen = {};
for (const g of p.mail_grenzen) grenzen[g.kunde_id] = g.grenze;
return [{ json: { ...p, grenzen, probelauf: l.probelauf, zusammenfassung: loeschen.zusammenfassung(p) } }];

// ----- Node-Logik -----
const p = $('Löschplan').first().json;
return [{ json: { ergebnis: 'probelauf', ...p.zusammenfassung, vorgaenge_ids: p.vorgaenge.map((v) => v.vorgangs_id), entwuerfe_freigaben: p.entwuerfe.map((e) => e.freigabe_id) } }];

// ----- Node-Logik -----
const p = $('Löschplan').first().json;
return p.entwuerfe.length ? p.entwuerfe.map((e) => ({ json: { ...e, vorhanden: true } })) : [{ json: { vorhanden: false } }];

// ----- Node-Logik -----
// Erledigt = gelöscht, schon weg oder kein passender Entwurf (dann nie wieder anfassen). Fehler: nächste Nacht erneut.
const auftraege = $('Entwürfe aufteilen').all().map((i) => i.json);
const jetzt = new Date().toISOString();
const erledigt = $input.all().map((it, i) => ({ r: it.json || {}, a: auftraege[i] })).filter((x) => x.a && !x.r.error && x.r.erledigt === true);
return erledigt.length ? erledigt.map((x) => ({ json: { freigabe_id: x.a.freigabe_id, entwurf_entfernt_am: jetzt } })) : [{ json: { freigabe_id: '__keiner__', entwurf_entfernt_am: jetzt } }];

// ----- Node-Logik -----
const p = $('Löschplan').first().json;
const liste = p.vorgaenge.map((v) => ({ json: { ...v, grenze: p.grenzen[v.kunde_id] } }));
return liste.length ? liste : [{ json: { kunde_id: '__keiner__', vorgangs_id: '__keiner__', grenze: new Date(0).toISOString() } }];

// ----- Node-Logik -----
const weg = new Set($('Vorgänge löschen').all().map((i) => i.json).filter((z) => z && z.id !== undefined).map((z) => z.kunde_id + '|' + z.vorgangs_id));
const p = $('Löschplan').first().json;
const liste = p.freigaben.filter((f) => weg.has(f.kunde_id + '|' + f.vorgangs_id)).map((f) => ({ json: { kunde_id: f.kunde_id, freigabe_id: f.freigabe_id } }));
return liste.length ? liste : [{ json: { kunde_id: '__keiner__', freigabe_id: '__keiner__' } }];

// ----- Node-Logik -----
const weg = new Set($('Vorgänge löschen').all().map((i) => i.json).filter((z) => z && z.id !== undefined).map((z) => z.kunde_id + '|' + z.vorgangs_id));
const liste = [...weg].map((k) => { const [kunde_id, vorgangs_id] = k.split('|'); return { json: { kunde_id, vorgangs_id } }; });
return liste.length ? liste : [{ json: { kunde_id: '__keiner__', vorgangs_id: '__keiner__' } }];

// ----- Node-Logik -----
const weg = new Set($('Vorgänge löschen').all().map((i) => i.json).filter((z) => z && z.id !== undefined).map((z) => z.kunde_id + '|' + z.vorgangs_id));
const liste = [...weg].map((k) => { const [kunde_id, vorgangs_id] = k.split('|'); return { json: { kunde_id, vorgangs_id } }; });
return liste.length ? liste : [{ json: { kunde_id: '__keiner__', vorgangs_id: '__keiner__' } }];

// ----- Node-Logik -----
const p = $('Löschplan').first().json;
const liste = p.mail_grenzen.map((g) => ({ json: g }));
return liste.length ? liste : [{ json: { kunde_id: '__keiner__', grenze: new Date(0).toISOString() } }];

// ----- Node-Logik -----
// Nur Zähler speichern, keine Inhalte.
const zahl = (n) => $(n).isExecuted ? $(n).all().filter((i) => i.json && i.json.id !== undefined).length : 0;
const p = $('Löschplan').first().json;
const ergebnis = {
	vorgaenge: zahl('Vorgänge löschen'), freigaben: zahl('Freigaben löschen'), links: zahl('Links löschen'), audit: zahl('Audit löschen'),
	dedupe: zahl('Dedupe-Einträge löschen'), fehlerlog: zahl('Fehlerlog löschen'), entwuerfe: zahl('Entwürfe vermerken'),
	zurueckgestellt: p.zurueckgestellt, verschoben: p.verschoben, ohne_config: p.ohne_config,
};
return [{ json: { schluessel: 'loeschjob', letzter_lauf: new Date().toISOString(), letztes_ergebnis: JSON.stringify(ergebnis) } }];
